const ic=(n,c="")=>`<svg class="ic ${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${IC[n]||""}</svg>`;

/* ================= helpers ================= */
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const $=id=>document.getElementById(id);
const toTop=()=>{const sc=document.getElementById("bsScroll");try{if(sc)sc.scrollTo({top:0,behavior:"smooth"});scrollTo({top:0,behavior:"smooth"})}catch(e){scrollTo(0,0)}};
const KINDS=[["","—"],["free","Grátis"],["paid","Pago"],["drive","Estrada"],["sleep","Pernoite"]];

// itens originais em objetos {t,h,d,k,c}
DAYS.forEach(x=>{x.items=x.items.map(a=>({t:a[0],h:a[1],d:a[2],k:a[3],c:a[4]}))});

/* ================= estado local ================= */
let store={}; try{store=JSON.parse(localStorage.getItem("nz27")||"{}")}catch(e){}
store.done=store.done||{}; store.doneAt=store.doneAt||0;
store.edits=store.edits||{};           // { n: {notes, items|null, stops|null, title|null, at} }
store.general=store.general||{text:"",at:0};
store.dirty=store.dirty||{};            // docs com mudanças ainda não enviadas
const save=()=>{try{localStorage.setItem("nz27",JSON.stringify(store))}catch(e){}};

function eff(i){
 const o=DAYS[i], e=store.edits[o.n]||{};
 const edited=!!(e.items||e.stops||e.title);
 return {...o,
  title:e.title||o.title,
  items:e.items||o.items,
  stops:e.stops||o.stops,
  stops2:e.stops?null:o.stops2,
  notes:e.notes||"", edited};
}
function setEdit(n,patch){
 store.edits[n]={...(store.edits[n]||{notes:"",items:null,stops:null,title:null}),...patch,at:Date.now()};
 store.dirty["d"+n]=true; save(); queuePush("d"+n);
}

const tripStart=new Date(2027,1,9), now=new Date();
const todayIdx=DAYS.findIndex(x=>now.getFullYear()===2027&&now.getMonth()===1&&now.getDate()===x.d);
let cur=todayIdx>=0?todayIdx:(typeof store.day==="number"?store.day:0);
let editing=null;   // rascunho {title,items,stops}
let proposal=null;  // proposta do Claude

/* ================= hero ================= */
function renderHero(){
 const ms=tripStart-new Date(now.getFullYear(),now.getMonth(),now.getDate());
 const days=Math.round(ms/864e5);
 const a=todayIdx>=0?`<span class="pill dark">Hoje é o dia ${DAYS[todayIdx].n}</span>`
   :days>0?`<span class="pill dark">Faltam ${days} dias</span>`:`<span class="pill dark">Boa viagem!</span>`;
 $("countdown").innerHTML=a+`<span class="pill">${ic("van")} 17 noites</span><span class="pill" id="syncPill"></span>`;
 renderSync();
 const sp=$("syncPill"); if(sp) sp.onclick=openAccount;
 const tb=$("tbSync"); if(tb) tb.onclick=openAccount;
}

/* ================= roteiro ================= */
const ISL={north:"Ilha Norte",south:"Ilha Sul",home:"Retorno"};
function renderChips(){
 $("chips").innerHTML=DAYS.map((x,i)=>{const e=eff(i);return `
  <div class="chip ${x.isl} ${i===cur?"on":""} ${i===todayIdx?"today":""}" data-i="${i}">
   <div class="d">Dia ${x.n}</div><div class="n">${x.d}</div><div class="w">${x.wd}</div>
   <div class="dot ${e.edited||e.notes?"mark":""}"></div></div>`}).join("");
 document.querySelectorAll(".chip").forEach(c=>c.onclick=()=>{if(editing&&!confirmLeave())return;showDay(+c.dataset.i)});
 const on=document.querySelector(".chip.on"),box=$("chips");
 if(on&&box){try{box.scrollTo({left:on.offsetLeft-box.clientWidth/2+on.clientWidth/2,behavior:"smooth"})}catch(e){box.scrollLeft=on.offsetLeft-box.clientWidth/2}}
}
let leaveArmed=false;
function confirmLeave(){ // sem confirm() (bloqueado em alguns visualizadores): 2º toque descarta
 if(leaveArmed){leaveArmed=false;editing=null;return true}
 leaveArmed=true; toast("Você está editando. Salve, ou toque de novo para descartar."); setTimeout(()=>leaveArmed=false,4000); return false;
}
function tag(k,c){
 if(!c) return "";
 const cls=String(c).startsWith("Grátis")||k==="free"?"free":k==="drive"?"drive":"paid";
 return `<span class="tag ${cls}">${esc(c)}</span>`;
}
function timelineHtml(items){
 return `<div class="tl">`+items.map(it=>`
  <div class="tl-item ${it.k==="sleep"?"sleep":""}"><div class="tl-time">${esc(it.t)}</div>
  <div class="tl-body"><h4>${esc(it.h)} ${tag(it.k,it.c)}</h4>${it.d?`<p>${esc(it.d)}</p>`:""}
  ${(it.k==="free"||it.k==="paid")&&it.h?`<a class="ph" href="${gi(it.h)}" target="_blank" rel="noopener">${ic("camera")} Ver fotos</a>`:""}</div></div>`).join("")+`</div>`;
}
function routeButtons(x){
 if(x.stops2) return `<div class="btn-row" style="margin-bottom:14px"><a class="btn dark" href="${gm(x.stops)}" target="_blank" rel="noopener">Rota até o ferry ↗</a><a class="btn dark" href="${gm(x.stops2)}" target="_blank" rel="noopener">Rota após o ferry ↗</a></div>`;
 if(x.stops.length>1) return `<a class="btn dark" style="margin-bottom:14px" href="${gm(x.stops)}" target="_blank" rel="noopener">${ic("route")} Abrir rota do dia no Google Maps</a>`;
 if(x.stops.length===1) return `<a class="btn dark" style="margin-bottom:14px" href="${gq(x.stops[0])}" target="_blank" rel="noopener">${ic("map")} Abrir no Google Maps</a>`;
 return "";
}

function showDay(i){
 cur=i; store.day=i; save();
 const x=eff(i), o=DAYS[i];
 let h=`<div class="card day-head">
   <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
    <span class="badge ${o.isl}">${ISL[o.isl]} · Dia ${o.n} de 18</span>
    ${editing?"":`<button class="mini" id="btnEdit">${ic("pencil")} Editar</button>`}
   </div>
   <h2>${esc(x.title)}</h2>
   <div class="date">${o.wd}, ${o.d} de fevereiro de 2027</div>
   <div class="meta">${o.sleep?`<span class="pill">${ic("moon")} ${esc(o.sleep)}</span>`:""}${o.cost?`<span class="pill">${o.cost}</span>`:""}${x.edited?`<span class="pill edited">Editado por vocês</span>`:""}</div>
 </div>`;
 if(o.alert) h+=`<div class="card alert"><div class="eyebrow">Alerta de logística</div><h3>Pernoite do dia 24</h3><p>${o.alert}</p></div>`;

 if(editing){ h+=editorHtml(); }
 else{
  if(proposal&&proposal.n===o.n) h+=proposalHtml();
  const da=attForDay(o.n);
  if(da.length) h+=`<div class="card"><div class="eyebrow" style="margin-bottom:4px">${ic("ticket","sm")} Ingressos e comprovantes do dia</div>${da.map(attRow).join("")}</div>`;
  h+=pointsListHtml(i);
  h+=`<div class="card">${timelineHtml(x.items)}</div>`+routeButtons(x);
  // anotações
  h+=`<div class="card notes-card"><div class="eyebrow">${ic("note","sm")} Anotações do dia</div>
   <textarea id="dayNotes" rows="3" placeholder="Ex.: reservar mesa, choveu, mudar parada, lembrar protetor...">${esc(x.notes)}</textarea>
   <div class="small" id="notesState">${x.notes?"Salvo":"Salva sozinho enquanto você escreve"}</div></div>`;
  // Claude
  if(sampleFn) h+=`<div class="card ai-card"><div class="eyebrow">${ic("sparkle","sm")} Pedir ao Claude</div>
   <h3>Mudar o plano deste dia</h3>
   <p class="small" style="margin-bottom:10px">Escreva o que mudou e o Claude reorganiza o dia e a rota. Você vê a proposta antes de aplicar.</p>
   <textarea id="aiAsk" rows="2" placeholder="Ex.: está chovendo, troque a trilha por algo coberto para a criança"></textarea>
   <button class="btn dark" id="aiGo" style="margin-top:10px">Replanejar com o Claude</button>
   <div id="aiOut" class="small" style="margin-top:10px"></div></div>`;
  if(o.extra) h+=`<div class="card extra"><div class="eyebrow">Extra opcional · não substitui nada</div><h3>${o.extra.t}</h3><p>${o.extra.x}</p><a href="${o.extra.l}" target="_blank" rel="noopener">${o.extra.lt}</a></div>`;
  h+=`<div class="btn-row">
   <button class="btn ghost" ${i===0?"disabled style='opacity:.35'":""} data-go="${i-1}">← Dia ${i}</button>
   <button class="btn ghost" ${i===DAYS.length-1?"disabled style='opacity:.35'":""} data-go="${i+1}">Dia ${i+2} →</button></div>`;
 }
 $("dayView").innerHTML=h;
 bindDay(); zoomAll($("dayView")); bindAtt($("dayView"));
 renderPeek(i); renderStage(i);
 renderChips();
}

function bindDay(){
 document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>{proposal=null;showDay(+b.dataset.go);toTop()});
 const be=$("btnEdit"); if(be) be.onclick=startEdit;
 const tn=$("dayNotes");
 if(tn){
  let t=null;
  tn.oninput=()=>{ $("notesState").textContent="Salvando…"; clearTimeout(t);
   t=setTimeout(()=>{ setEdit(DAYS[cur].n,{notes:tn.value}); $("notesState").textContent="Salvo"; renderChips(); renderResumo(); },700) };
  tn.onblur=()=>{ if(pendingRender){pendingRender=false;setTimeout(()=>showDay(cur),50)} };
 }
 const ag=$("aiGo"); if(ag) ag.onclick=askClaude;
 const pa=$("propApply"); if(pa) pa.onclick=()=>{ setEdit(proposal.n,{title:proposal.title,items:proposal.items,stops:proposal.stops,places:[...((store.edits[proposal.n]||{}).places||[]),...proposal.places].slice(-30)}); proposal=null; showDay(cur); renderResumo(); toast("Dia atualizado"); };
 const pd=$("propDrop"); if(pd) pd.onclick=()=>{ proposal=null; showDay(cur); };
 if(editing) bindEditor();
}

/* ================= editor manual ================= */
function startEdit(){
 const x=eff(cur);
 editing={title:x.title,items:x.items.map(it=>({...it})),stops:[...x.stops,...(x.stops2||[])]};
 proposal=null; showDay(cur);
}
function editorHtml(){
 const e=editing;
 return `<div class="card editor">
  <div class="eyebrow">Editando o dia</div>
  <label class="lbl">Título</label><input class="inp" data-f="title" value="${esc(e.title)}">
  <label class="lbl" style="margin-top:16px">Atividades</label>
  ${e.items.map((it,j)=>`
   <div class="ed-item">
    <div class="ed-row"><input class="inp sm" data-i="${j}" data-k="t" value="${esc(it.t)}" placeholder="Horário">
     <select class="inp sm" data-i="${j}" data-k="k">${KINDS.map(k=>`<option value="${k[0]}" ${it.k===k[0]?"selected":""}>${k[1]}</option>`).join("")}</select>
     <input class="inp sm" data-i="${j}" data-k="c" value="${esc(it.c)}" placeholder="Custo"></div>
    <input class="inp" data-i="${j}" data-k="h" value="${esc(it.h)}" placeholder="Atividade">
    <textarea class="inp" rows="2" data-i="${j}" data-k="d" placeholder="Detalhes">${esc(it.d)}</textarea>
    <div class="ed-act"><button class="mini" data-mv="${j}" data-dir="-1" ${j===0?"disabled":""}>↑</button><button class="mini" data-mv="${j}" data-dir="1" ${j===e.items.length-1?"disabled":""}>↓</button><button class="mini danger" data-rm="${j}">Remover</button></div>
   </div>`).join("")}
  <button class="btn ghost" id="addItem">+ Adicionar atividade</button>
  <label class="lbl" style="margin-top:18px">Paradas da rota (na ordem)</label>
  <p class="small" style="margin-bottom:8px">Use nomes que o Google Maps encontre. O botão de rota muda junto.</p>
  ${e.stops.map((s,j)=>`<div class="stop-row"><span class="stop-n">${j+1}</span><input class="inp" data-s="${j}" value="${esc(s)}">
    <button class="mini" data-smv="${j}" data-dir="-1" ${j===0?"disabled":""}>↑</button><button class="mini" data-smv="${j}" data-dir="1" ${j===e.stops.length-1?"disabled":""}>↓</button><button class="mini danger" data-srm="${j}">✕</button></div>`).join("")}
  <button class="btn ghost" id="addStop">+ Adicionar parada</button>
  <a class="small" style="display:block;text-align:center;margin-top:10px;color:var(--north);font-weight:600" href="${gm(e.stops.filter(Boolean))}" target="_blank" rel="noopener">Testar esta rota no Maps ↗</a>
  <div class="btn-row" style="margin-top:18px"><button class="btn ghost" id="edCancel">Cancelar</button><button class="btn dark" id="edSave">Salvar</button></div>
  ${eff(cur).edited?`<button class="btn ghost" id="edReset" style="margin-top:10px;color:var(--alert)">Voltar ao roteiro original</button>`:""}
 </div>`;
}
function bindEditor(){
 const e=editing;
 document.querySelectorAll(".editor [data-f='title']").forEach(el=>el.oninput=()=>e.title=el.value);
 document.querySelectorAll(".editor [data-k]").forEach(el=>el.oninput=el.onchange=()=>{e.items[+el.dataset.i][el.dataset.k]=el.value});
 document.querySelectorAll(".editor [data-s]").forEach(el=>el.oninput=()=>{e.stops[+el.dataset.s]=el.value});
 document.querySelectorAll("[data-mv]").forEach(b=>b.onclick=()=>{const j=+b.dataset.mv,k=j+ +b.dataset.dir;[e.items[j],e.items[k]]=[e.items[k],e.items[j]];showDay(cur)});
 document.querySelectorAll("[data-rm]").forEach(b=>b.onclick=()=>{e.items.splice(+b.dataset.rm,1);showDay(cur)});
 document.querySelectorAll("[data-smv]").forEach(b=>b.onclick=()=>{const j=+b.dataset.smv,k=j+ +b.dataset.dir;[e.stops[j],e.stops[k]]=[e.stops[k],e.stops[j]];showDay(cur)});
 document.querySelectorAll("[data-srm]").forEach(b=>b.onclick=()=>{e.stops.splice(+b.dataset.srm,1);showDay(cur)});
 $("addItem").onclick=()=>{e.items.push({t:"",h:"",d:"",k:"",c:""});showDay(cur)};
 $("addStop").onclick=()=>{e.stops.push("");showDay(cur)};
 $("edCancel").onclick=()=>{editing=null;showDay(cur)};
 $("edSave").onclick=()=>{
  const items=e.items.filter(it=>it.h.trim()||it.t.trim()).map(it=>({t:it.t.trim(),h:it.h.trim(),d:it.d.trim(),k:it.k,c:it.c.trim()}));
  const stops=e.stops.map(s=>s.trim()).filter(Boolean);
  setEdit(DAYS[cur].n,{title:e.title.trim()||DAYS[cur].title,items,stops});
  editing=null; showDay(cur); renderResumo(); toast("Dia salvo");
 };
 const r=$("edReset"); if(r) r.onclick=()=>{ setEdit(DAYS[cur].n,{title:null,items:null,stops:null}); editing=null; showDay(cur); renderResumo(); toast("Voltou ao original"); };
}

/* ================= painel estilo Uber ================= */
function nextItem(x){
 const its=x.items.filter(it=>it.k!=="drive"&&it.k!=="sleep"&&it.h);
 if(DAYS[cur]&&cur===todayIdx){
  const n=new Date(), mins=n.getHours()*60+n.getMinutes();
  const f=its.find(it=>{const m=String(it.t).match(/(\d{1,2}):(\d{2})(?:\D+(\d{1,2}):(\d{2}))?/); if(!m) return false; const end=m[3]?(+m[3]*60+ +m[4]):(+m[1]*60+ +m[2]+60); return end>=mins;});
  return f?{lbl:"Agora / próximo",it:f}:null;
 }
 return its[0]?{lbl:"Primeira parada",it:its[0]}:null;
}
function renderPeek(i){
 const el=$("peek"); if(!el) return; const x=eff(i), o=DAYS[i], nx=nextItem(x);
 const st=[...x.stops,...(x.stops2||[])];
 const rt=x.stops2?gm(x.stops):(st.length>1?gm(st):gq(st[0]||"New Zealand"));
 el.innerHTML=`<div class="pk-top"><span class="badge ${o.isl}">Dia ${o.n} · ${o.wd}, ${o.d} fev</span>${x.edited?'<span class="tag paid">editado</span>':""}</div>
  <h2 class="pk-title">${esc(x.title)}</h2>
  ${nx?`<div class="pk-next"><span class="pk-dot"></span><div><small>${nx.lbl} · ${esc(nx.it.t)}</small><b>${esc(nx.it.h)}</b></div></div>`:""}
  <div class="pk-btns"><a class="btn dark" href="${rt}" target="_blank" rel="noopener">${x.stops2?"Rota até o ferry":"Iniciar rota"} ↗</a><button class="btn ghost" id="pkMore">Ver o dia</button></div>`;
 $("pkMore").onclick=()=>setSheet(sheetState==="full"?"half":"full");
}
let sheetState="peek";
function sheetY(state){ // distância do topo do painel até o topo da tela
 const H=innerHeight, pk=$("peek"), peekH=(pk?pk.offsetHeight:190)+34+(document.querySelector(".bs-seg")||{offsetHeight:0}).offsetHeight*0;
 const nav=(document.querySelector("nav.tabs")||{offsetHeight:60}).offsetHeight+22;
 if(state==="full") return Math.max(70,H*0.08);
 if(state==="half") return H*0.48;
 return H-peekH-nav;
}
function setSheet(state,instant){
 sheetState=state; const sh=$("sheet"); if(!sh) return;
 sh.style.transition=instant?"none":""; sh.style.transform=`translateY(${sheetY(state)}px)`;
 sh.classList.toggle("is-full",state==="full");
}
function initSheet(){
 const sh=$("sheet"), sc=$("bsScroll"); if(!sh) return;
 let y0=null,t0=0,base=0,dragging=false,lastY=0,lastT=0,vel=0;
 const curY=()=>{const m=/translateY\(([-\d.]+)px\)/.exec(sh.style.transform);return m?+m[1]:sheetY(sheetState)};
 const start=(y)=>{y0=y;base=curY();dragging=false;lastY=y;lastT=performance.now();vel=0};
 const move=(y,e)=>{
  if(y0===null) return; const dy=y-y0;
  if(!dragging){
   const atTop=sc.scrollTop<=0, fromHandle=e&&e.target&&e.target.closest&&e.target.closest(".bs-handle,#peek .pk-top,.pk-title");
   if(Math.abs(dy)<6) return;
   if(fromHandle||sheetState!=="full"||(atTop&&dy>0)) dragging=true; else {y0=null;return}
   sh.style.transition="none";
  }
  e&&e.cancelable&&e.preventDefault();
  const ny=Math.min(Math.max(base+dy,sheetY("full")-20),innerHeight-80); sh.style.transform=`translateY(${ny}px)`;
  const now=performance.now(); vel=(y-lastY)/Math.max(now-lastT,1); lastY=y; lastT=now;
 };
 const end=()=>{
  if(y0===null) return; y0=null; if(!dragging) return; dragging=false;
  const y=curY(), opts=["full","half","peek"].map(s=>[s,sheetY(s)]);
  let target;
  if(vel<-0.5) target=opts.filter(o=>o[1]<y-10).pop()||opts[0];
  else if(vel>0.5) target=opts.find(o=>o[1]>y+10)||opts[2];
  else target=opts.reduce((a,b)=>Math.abs(b[1]-y)<Math.abs(a[1]-y)?b:a);
  setSheet(target[0]);
 };
 sh.addEventListener("touchstart",e=>{ if(e.target.closest("input,textarea,select,.zctl")) return; start(e.touches[0].clientY)},{passive:true});
 sh.addEventListener("touchmove",e=>move(e.touches[0].clientY,e),{passive:false});
 sh.addEventListener("touchend",end); sh.addEventListener("touchcancel",end);
 const hd=sh.querySelector(".bs-handle");
 hd.addEventListener("mousedown",e=>{start(e.clientY);const mm=ev=>move(ev.clientY,ev),mu=()=>{end();removeEventListener("mousemove",mm);removeEventListener("mouseup",mu)};addEventListener("mousemove",mm);addEventListener("mouseup",mu)});
 hd.addEventListener("click",()=>{ if(!dragging) setSheet(sheetState==="peek"?"half":sheetState==="half"?"full":"peek") });
 addEventListener("resize",()=>{setSheet(sheetState,true);renderStage(cur)});
 setSheet("peek",true);
}

/* ================= Claude replaneja ================= */
let sampleFn=null, aiBusy=false;
function proposalHtml(){
 const p=proposal;
 return `<div class="card ai-card"><div class="eyebrow">${ic("sparkle","sm")} Proposta do Claude</div>
  <h3>${esc(p.title)}</h3><p style="font-size:13.5px;margin-bottom:8px">${esc(p.resumo)}</p>
  <div class="map-wrap" style="margin:10px 0">${mapSvg(p.stops.map(n=>({name:n,ll:llOf(n,p.places)})))}</div>
  ${timelineHtml(p.items)}
  <p class="small" style="margin:8px 0 12px">Rota: ${p.stops.map(esc).join(" → ")}</p>
  <div class="btn-row"><button class="btn ghost" id="propDrop">Descartar</button><button class="btn dark" id="propApply">Aplicar ao dia</button></div></div>`;
}
async function askClaude(){
 if(aiBusy) return;
 const ask=($("aiAsk").value||"").trim(); const out=$("aiOut");
 if(!ask){out.textContent="Escreva primeiro o que mudou.";return}
 aiBusy=true; $("aiGo").disabled=true; out.textContent="O Claude está replanejando…";
 const x=eff(cur), prev=cur>0?DAYS[cur-1]:null, next=cur<DAYS.length-1?DAYS[cur+1]:null;
 const prompt=`Você ajuda uma família (2 adultos + 1 criança) numa viagem de motorhome self-contained pela Nova Zelândia em fevereiro de 2027. Replaneje UM dia do roteiro conforme o pedido.

Regras:
- Responda em português do Brasil.
- Mantenha o pernoite e o ponto final do dia, a menos que o pedido diga outra coisa, porque o dia seguinte começa de lá.
- Mantenha passeios pagos com horário marcado (ferry, tours) a menos que o pedido peça para mudar.
- Horários realistas de estrada para motorhome. Não invente preços: deixe "c" vazio se não souber, use "Grátis" só para o que é claramente gratuito.
- "stops" são nomes de lugares que o Google Maps encontra, na ordem da rota (2 a 9 paradas).

Dia anterior termina em: ${prev?prev.sleep:"(início da viagem, Auckland Airport)"}
Dia seguinte começa e vai para: ${next?next.title:"(fim da viagem)"}

Dia atual (${DAYS[cur].wd}, ${DAYS[cur].d} fev, dia ${DAYS[cur].n}):
${JSON.stringify({title:x.title,pernoite:DAYS[cur].sleep,items:x.items,stops:[...x.stops,...(x.stops2||[])],anotacoes:x.notes})}

Pedido: ${ask}

Responda SOMENTE com JSON neste formato:
{"resumo":"1-2 frases dizendo o que mudou","title":"título curto do dia","items":[{"t":"horário","h":"atividade","d":"detalhes","k":"free|paid|drive|sleep|","c":"custo ou vazio"}],"stops":["lugar 1","lugar 2"],"coords":[{"name":"lugar 1","lat":-41.0,"lng":174.0}]}
"coords" traz latitude e longitude aproximadas de cada parada em "stops", com o mesmo nome.`;
 try{
  let r;
  if(typeof sampleFn.json==="function"){ r=await sampleFn.json(prompt,{modelTier:"default"}); }
  else{ const t=(await sampleFn(prompt,{modelTier:"default"})).text; r=JSON.parse(t.slice(t.indexOf("{"),t.lastIndexOf("}")+1)); }
  if(!r||!Array.isArray(r.items)||!Array.isArray(r.stops)) throw {message:"resposta incompleta"};
  const ok=k=>["free","paid","drive","sleep",""].includes(k)?k:"";
  proposal={n:DAYS[cur].n,resumo:String(r.resumo||""),title:String(r.title||x.title).slice(0,120),
   items:r.items.slice(0,15).map(it=>({t:String(it.t||""),h:String(it.h||""),d:String(it.d||""),k:ok(it.k),c:String(it.c||"")})),
   stops:r.stops.slice(0,10).map(String).filter(Boolean),
   places:(Array.isArray(r.coords)?r.coords:[]).filter(c=>c&&isFinite(c.lat)&&isFinite(c.lng)&&c.lat<-33&&c.lat>-48&&c.lng>165&&c.lng<179).slice(0,10).map(c=>({name:String(c.name),lat:+c.lat,lng:+c.lng}))};
  showDay(cur);
 }catch(e){
  const c=e&&e.code;
  out.textContent=c==="not_granted"?"O Claude não está disponível nesta visualização."
   :c==="rate_limited"?"Muitos pedidos seguidos. Espere um pouco e tente de novo."
   :"Não deu certo desta vez. Tente de novo ou edite à mão.";
  if(c==="not_granted"){sampleFn=null;}
 }finally{aiBusy=false; const g=$("aiGo"); if(g) g.disabled=false;}
}

