/* ================= sincronização ================= */
let db=null, syncState="local", readOnly=false, pendingRender=false, pendingGeneral=false;
const SYNC_TXT={local:"Só neste aparelho · entrar",connecting:"Conectando…",ok:"Sincronizado",offline:"Sem sinal · salvo no aparelho",readonly:"Só leitura"};
const SYNC_IC={local:"phone",connecting:"clock",ok:"cloud",offline:"alert",readonly:"eye"};
function renderSync(){const p=$("syncPill"); if(p) p.innerHTML=ic(SYNC_IC[syncState]||"phone")+" "+(SYNC_TXT[syncState]||SYNC_TXT.local);
 const t=$("tbSync"); if(t){t.innerHTML=ic(SYNC_IC[syncState]||"phone"); t.title=SYNC_TXT[syncState]||""}}
function setSync(s){syncState=s;renderSync()}

function bodyFor(key){
 if(key.startsWith("l_")){const L=store.lists[key.slice(2)];return L?{name:L.name,items:L.items,at:L.at,deleted:!!L.deleted}:null}
 if(key==="listorder") return {order:store.listOrder,at:store.listOrderAt||0};
 if(key==="bookings") return {done:store.done,at:store.doneAt};
 if(key==="general") return {text:store.general.text,at:store.general.at};
 const e=store.edits[key.slice(1)]; return e?{notes:e.notes||"",title:e.title||null,items:e.items||null,stops:e.stops||null,places:e.places||[],at:e.at}:null;
}
function refFor(key){ return key.startsWith("l_")?db.collection("lists").doc(key.slice(2)):key.startsWith("d")?db.collection("days").doc(key):db.doc("meta/"+key); }
const timers={}, chains={};
function queuePush(key){
 if(!db||readOnly) return;
 clearTimeout(timers[key]);
 timers[key]=setTimeout(()=>{
  chains[key]=(chains[key]||Promise.resolve()).then(async()=>{
   const body=bodyFor(key); if(!body) return;
   try{ await refFor(key).set(JSON.parse(JSON.stringify(body))); delete store.dirty[key]; save(); if(syncState!=="readonly") setSync("ok"); }
   catch(e){
    if(e&&e.code==="invalid_argument"){ readOnly=true; setSync("readonly"); }
    else if(e&&e.code==="unavailable"){ setSync("offline"); setTimeout(()=>queuePush(key),4000+Math.random()*3000); }
    else setSync("offline");
   }
  });
 },600);
}
function pushDirty(){ Object.keys(store.dirty).forEach(queuePush); }

function applyRemoteDay(id,data){
 if(!data||!/^d\d+$/.test(id)) return false;
 const n=id.slice(1), loc=store.edits[n], at=+data.at||0;
 if(loc&&(+loc.at||0)>=at) return false;
 const arr=v=>Array.isArray(v)?v:null;
 store.edits[n]={notes:String(data.notes||""),title:data.title?String(data.title):null,
  items:arr(data.items)?data.items.map(it=>({t:String(it&&it.t||""),h:String(it&&it.h||""),d:String(it&&it.d||""),k:String(it&&it.k||""),c:String(it&&it.c||"")})):null,
  stops:arr(data.stops)?data.stops.map(String):null,
  places:arr(data.places)?data.places.filter(p=>p&&isFinite(p.lat)&&isFinite(p.lng)).map(p=>({name:String(p.name),lat:+p.lat,lng:+p.lng})):[],at};
 delete store.dirty[id]; return true;
}
function rerenderAfterRemote(){
 save(); renderResumo(); renderMaps(); renderTripMap();
 const a=document.activeElement;
 if(editing||(a&&$("dayView").contains(a)&&a.tagName==="TEXTAREA")) pendingRender=true; else showDay(cur);
}

async function initSync(){
 if(!(window.claude&&typeof window.claude.use==="function")){ setSync("local"); return; }
 try{
  const s=await window.claude.use("sample");
  if(s){ sampleFn=s; showDayIfIdle(); }
 }catch(e){}
 let d=null; try{ d=await window.claude.use("db"); }catch(e){}
 if(!d){ setSync("local"); return; }
 db=d; setSync("connecting");
 try{ const u=await window.claude.use("user"); if(u&&typeof u.can==="function"){ const w=await u.can("data.write"); if(w===false){readOnly=true;} } }catch(e){}
 let firstDays=true;
 const timer=setTimeout(()=>{ if(syncState==="connecting") setSync("offline") },10000);
 db.collection("days").onSnapshot(snap=>{
  let changed=false;
  snap.docs.forEach(doc=>{ if(doc.exists&&applyRemoteDay(doc.id,doc.data())) changed=true; });
  if(changed) rerenderAfterRemote();
  if(!snap.metadata.fromCache){ clearTimeout(timer); setSync(readOnly?"readonly":"ok");
   if(firstDays){ firstDays=false; setTimeout(pushDirty,0); } }
 },e=>{ clearTimeout(timer); setSync("offline"); });
 db.doc("meta/bookings").onSnapshot(doc=>{
  if(!doc.exists) return; const v=doc.data();
  if((+v.at||0)>store.doneAt&&v.done&&typeof v.done==="object"){ store.done={...v.done}; store.doneAt=+v.at; delete store.dirty.bookings; save(); renderBook(); }
 },()=>{});
 db.doc("meta/general").onSnapshot(doc=>{
  if(!doc.exists) return; const v=doc.data();
  if((+v.at||0)>store.general.at){ store.general={text:String(v.text||""),at:+v.at}; delete store.dirty.general; save();
   if(document.activeElement&&document.activeElement.id==="genNotes") pendingGeneral=true; else renderNotes(); }
 },()=>{});
 try{ assetsApi=await window.claude.use("assets"); }catch(e){ assetsApi=null; }
 db.collection("docs").onSnapshot(snap=>{
  remoteAtt=snap.docs.filter(d=>d.exists).map(d=>{const v=d.data()||{};return {rid:d.id,title:String(v.title||""),link:String(v.link||""),assetId:String(v.assetId||""),type:String(v.type||""),name:String(v.name||""),size:+v.size||0,at:+v.at||0}}).filter(a=>/^[A-Za-z0-9_-]{8,64}$/.test(a.assetId));
  refreshAtt(); prefetchAtt();
 },()=>{});
 refreshAtt();
 db.collection("lists").onSnapshot(snap=>{
  let ch=false;
  snap.docs.forEach(doc=>{ if(!doc.exists) return; const v=doc.data(), id=doc.id, loc=store.lists[id];
   if(loc&&(+loc.at||0)>=(+v.at||0)) return;
   store.lists[id]={name:String(v.name||"Lista"),deleted:!!v.deleted,at:+v.at||0,
    items:(Array.isArray(v.items)?v.items:[]).map(it=>({id:String(it&&it.id||uid()),text:String(it&&it.text||""),done:!!(it&&it.done)}))};
   if(!store.listOrder.includes(id)) store.listOrder.push(id);
   delete store.dirty["l_"+id]; ch=true; });
  if(ch){ save(); const a=document.activeElement; if(!(a&&a.closest&&a.closest("#listsView"))) renderLists(); }
 },()=>{});
 db.doc("meta/listorder").onSnapshot(doc=>{
  if(!doc.exists) return; const v=doc.data();
  if((+v.at||0)>(store.listOrderAt||0)&&Array.isArray(v.order)){ const o=v.order.map(String); Object.keys(store.lists).forEach(k=>{if(!o.includes(k))o.push(k)}); store.listOrder=o; store.listOrderAt=+v.at; save(); renderLists(); }
 },()=>{});
 if(readOnly) setSync("readonly");
}
