const DEFAULT_LISTS=[
 {id:"afazer",name:"A fazer",items:[["Baixar mapas offline da NZ",0],["Confirmar marés (Hot Water Beach e Tongaporutu)",0],["Anotar endereço da locadora e horário do voo",0],["Definir pernoite do dia 24 perto de Wellington (ferry chega 22:45)",0]]},
 {id:"mala",name:"Mala",items:[["Protetor solar",0],["Casacos para o glaciar e Milford",0],["Roupa de banho (Hot Water Beach, Tekapo)",0],["Tênis de trilha",0]]},
 {id:"mercado",name:"Mercado",items:[["Água",0],["Lanches para a estrada",0]]}
];
store.lists=store.lists||{};
store.listOrder=store.listOrder||null;
DEFAULT_LISTS.forEach(l=>{ if(!store.lists[l.id]) store.lists[l.id]={name:l.name,items:l.items.map((a,j)=>({id:l.id+j,text:a[0],done:false})),at:0}; });
if(!store.listOrder) store.listOrder=DEFAULT_LISTS.map(l=>l.id);
let curList=store.curList&&store.lists[store.curList]?store.curList:store.listOrder[0];
const uid=()=>Math.random().toString(36).slice(2,9);
function touchList(id){ store.lists[id].at=Date.now(); store.dirty["l_"+id]=true; save(); queuePush("l_"+id); }
function renderLists(){
 const ids=store.listOrder.filter(id=>store.lists[id]&&!store.lists[id].deleted);
 if(!ids.includes(curList)) curList=ids[0];
 const L=store.lists[curList];
 const done=L?L.items.filter(i=>i.done).length:0;
 $("listsView").innerHTML=`
  <div class="chips list-tabs">${ids.map(id=>`<button class="lt ${id===curList?"on":""}" data-l="${id}">${esc(store.lists[id].name)} <span>${store.lists[id].items.filter(i=>!i.done).length}</span></button>`).join("")}<button class="lt add" id="newList">+ Lista</button></div>
  ${L?`<div class="card">
   <div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px"><h3 class="ct">${esc(L.name)}</h3><span class="small">${done} de ${L.items.length}</span></div>
   <div class="prog"><i style="width:${L.items.length?done/L.items.length*100:0}%"></i></div>
   <form id="addForm" class="add-row"><input class="inp" id="addTxt" placeholder="Adicionar item…" autocomplete="off"><button class="mini dark" type="submit">Adicionar</button></form>
   <div id="itemsBox">${L.items.map(it=>`<div class="ck li ${it.done?"done":""}" data-id="${it.id}"><div class="box"></div><div class="txt"><h4>${esc(it.text)}</h4></div><button class="x" data-del="${it.id}" aria-label="Remover">✕</button></div>`).join("")||`<p class="small" style="padding:12px 0">Lista vazia. Adicione o primeiro item acima.</p>`}</div>
   <div class="btn-row" style="margin-top:12px">${done?`<button class="btn ghost" id="clearDone">Limpar marcados</button>`:""}<button class="btn ghost" id="renList">Renomear</button><button class="btn ghost" id="delList" style="color:var(--alert)">Apagar lista</button></div>
  </div>`:""}
  <div id="listDialog"></div>`;
 document.querySelectorAll(".lt[data-l]").forEach(b=>b.onclick=()=>{curList=b.dataset.l;store.curList=curList;save();renderLists()});
 $("newList").onclick=()=>listDialog("Nome da nova lista","",name=>{const id="l"+uid();store.lists[id]={name,items:[],at:0};store.listOrder.push(id);curList=id;touchList(id);pushOrder();renderLists()});
 if(!L) return;
 $("addForm").onsubmit=e=>{e.preventDefault();const v=$("addTxt").value.trim();if(!v)return;L.items.push({id:uid(),text:v,done:false});touchList(curList);renderLists();setTimeout(()=>{const t=$("addTxt");if(t)t.focus()},0)};
 document.querySelectorAll(".li").forEach(r=>r.onclick=e=>{if(e.target.closest(".x"))return;const it=L.items.find(i=>i.id===r.dataset.id);if(it){it.done=!it.done;touchList(curList);renderLists()}});
 document.querySelectorAll("[data-del]").forEach(b=>b.onclick=()=>{L.items=L.items.filter(i=>i.id!==b.dataset.del);touchList(curList);renderLists()});
 const cd=$("clearDone"); if(cd) cd.onclick=()=>{L.items=L.items.filter(i=>!i.done);touchList(curList);renderLists()};
 $("renList").onclick=()=>listDialog("Novo nome da lista",L.name,name=>{L.name=name;touchList(curList);renderLists()});
 let armed=false; $("delList").onclick=()=>{ if(!armed){armed=true;$("delList").textContent="Toque de novo para apagar";setTimeout(()=>{armed=false;const b=$("delList");if(b)b.textContent="Apagar lista"},3500);return}
   L.deleted=true;L.items=[];touchList(curList);curList=null;renderLists();toast("Lista apagada")};
}
