 $("listDialog").innerHTML=`<div class="card"><h3 class="ct" style="margin-bottom:10px">${title}</h3><form id="dlgF" class="add-row"><input class="inp" id="dlgT" value="${esc(val)}" autocomplete="off"><button class="mini dark" type="submit">OK</button></form><button class="mini" id="dlgC" style="margin-top:8px">Cancelar</button></div>`;
