/* ================= anexos: ingressos e comprovantes ================= */
const LINK_DAY={rv:1,"ferry-ida":6,"ferry-volta":15,waitomo:3,heli:8,skyline:9,kiwipark:10,milford:11,tekapo:14,whale:15,hobbiton:16,
 c10:2,c11:3,c14:6,c15:7,c16:8,c17:9,c18:10,c21:13,c22:14,c25:17};
const BOOK_NAME={}; BOOK.forEach(g=>g.items.forEach(it=>BOOK_NAME[it[0]]=it[1]));
let assetsApi=null, remoteAtt=[]; // remoteAtt: [{rid,title,link,assetId,type,name,size,at}]
store.attLocal=store.attLocal||[]; // [{lid,title,link,type,name,size,at}] blob em IndexedDB
function idb(){return new Promise((res,rej)=>{try{const r=indexedDB.open("nz27files",1);r.onupgradeneeded=()=>r.result.createObjectStore("f");r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}catch(e){rej(e)}})}
async function idbPut(k,v){const d=await idb();return new Promise((res,rej)=>{const t=d.transaction("f","readwrite");t.objectStore("f").put(v,k);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function idbGet(k){const d=await idb();return new Promise((res,rej)=>{const q=d.transaction("f").objectStore("f").get(k);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}
async function idbDel(k){const d=await idb();return new Promise(res=>{const t=d.transaction("f","readwrite");t.objectStore("f").delete(k);t.oncomplete=res;t.onerror=res})}
const urlCache={};
async function localUrl(lid){ if(urlCache[lid]) return urlCache[lid]; const b=await idbGet(lid); if(!b) return null; return urlCache[lid]=URL.createObjectURL(b); }

function allAtt(){
 return [...remoteAtt.map(a=>({...a,key:"r:"+a.rid,remote:true})),...store.attLocal.map(a=>({...a,key:"l:"+a.lid,remote:false}))].sort((a,b)=>(b.at||0)-(a.at||0));
}
function attFor(link){return allAtt().filter(a=>a.link===link)}
function attForDay(n){return allAtt().filter(a=>a.link==="day:"+n||LINK_DAY[a.link]===n)}
function linkLabel(l){ if(!l) return "Sem vínculo"; if(l.startsWith("day:")){const d=DAYS.find(x=>x.n==+l.slice(4));return d?`Dia ${d.n} · ${d.d} fev`:"Dia"} return BOOK_NAME[l]||l; }
const isImg=t=>/^image\//.test(t||"");
function thumbHtml(a){
 return isImg(a.type)?(a.remote?`<img class="th" data-rid="${esc(a.assetId)}" alt="">`:`<img class="th" data-lid="${esc(a.lid)}" alt="">`):`<span class="th pdf">PDF</span>`;
}
async function remoteUrl(id){
 const k="r:"+id; if(urlCache[k]) return urlCache[k];
 let b=null; try{ b=await idbGet(k) }catch(e){}
 if(!b){ b=await window.NZ_FETCH_ASSET(id); try{ await idbPut(k,b) }catch(e){} }
 return urlCache[k]=URL.createObjectURL(b);
}
function prefetchAtt(){ remoteAtt.forEach(a=>{ if(!urlCache["r:"+a.assetId]) remoteUrl(a.assetId).catch(()=>{}) }); }
function attRow(a){
 return `<button class="att" data-k="${esc(a.key)}">${thumbHtml(a)}<span class="att-t"><b>${esc(a.title||a.name||"Anexo")}</b><small>${esc(linkLabel(a.link))}${a.remote?"":" · só neste aparelho"}</small></span><span class="pt-go">Abrir</span></button>`;
}
function hydrateThumbs(root){
 (root||document).querySelectorAll("img.th[data-rid]").forEach(async im=>{try{im.src=await remoteUrl(im.dataset.rid)}catch(e){im.replaceWith(Object.assign(document.createElement("span"),{className:"th pdf",textContent:"IMG"}))}});
 (root||document).querySelectorAll("img.th[data-lid]").forEach(async im=>{const u=await localUrl(im.dataset.lid).catch(()=>null); if(u) im.src=u; else im.replaceWith(Object.assign(document.createElement("span"),{className:"th pdf",textContent:"?"}))}); }
function bindAtt(root){ (root||document).querySelectorAll(".att").forEach(b=>b.onclick=()=>openViewer(b.dataset.k)); hydrateThumbs(root); }

function attCardHtml(){
 const list=allAtt();
 return `<div class="card" id="attCard"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><h3 class="ct">Ingressos e comprovantes</h3><button class="mini dark" data-attach="">+ Anexar</button></div>
  <p class="small" style="margin:4px 0 8px">Foto ou PDF de ingressos, reservas e recibos. Cada um aparece também no dia em que vocês vão usar.</p>
  ${list.length?list.map(attRow).join(""):`<p class="small" style="padding:10px 0">Nada anexado ainda.</p>`}
  ${!db?`<p class="small" style="margin-top:8px">Você não entrou na sua conta: os anexos ficam salvos só neste aparelho. Toque em "Só neste aparelho · entrar" no topo para sincronizar.</p>`:`<p class="small" style="margin-top:8px">Os anexos ficam guardados também no celular, para abrir sem sinal.</p>`}</div>`;
}

/* ---- formulário ---- */
function openAttachForm(link){
 const opts=[["","Sem vínculo"],...BOOK.flatMap(g=>g.items.map(it=>[it[0],it[1]])),...DAYS.map(d=>["day:"+d.n,`Dia ${d.n} · ${d.d} fev · ${eff(DAYS.indexOf(d)).title}`])];
 const ov=document.createElement("div"); ov.className="sheet";
 ov.innerHTML=`<div class="sheet-box"><h3 class="ct" style="margin-bottom:12px">Anexar ingresso ou comprovante</h3>
  <label class="lbl">Arquivo (foto ou PDF)</label><input type="file" id="atFile" accept="image/*,application/pdf" class="inp">
  <label class="lbl">Nome</label><input class="inp" id="atTitle" placeholder="Ex.: Ingressos Hobbiton">
  <label class="lbl">Ligado a</label><select class="inp" id="atLink">${opts.map(o=>`<option value="${esc(o[0])}" ${o[0]===link?"selected":""}>${esc(o[1])}</option>`).join("")}</select>
  <div class="small" id="atMsg" style="min-height:18px;margin:8px 0"></div>
  <div class="btn-row"><button class="btn ghost" id="atCancel">Cancelar</button><button class="btn dark" id="atSave">Salvar</button></div></div>`;
 document.body.appendChild(ov); document.body.classList.add("noscroll");
 const close=()=>{ov.remove();document.body.classList.remove("noscroll")};
 ov.onclick=e=>{if(e.target===ov)close()}; $("atCancel").onclick=close;
 $("atFile").onchange=()=>{const f=$("atFile").files[0]; if(f&&!$("atTitle").value) $("atTitle").value=(link&&BOOK_NAME[link]?BOOK_NAME[link].split(" · ")[0]:f.name.replace(/\.[^.]+$/,"")).slice(0,60)};
 $("atSave").onclick=async()=>{
  const f=$("atFile").files[0], msg=$("atMsg"); if(!f){msg.textContent="Escolha um arquivo.";return}
  if(!isImg(f.type)&&f.type!=="application/pdf"){msg.textContent="Use uma foto ou um PDF.";return}
  $("atSave").disabled=true; msg.textContent="Preparando…";
  try{
   let blob=f, type=f.type;
   if(isImg(type)&&f.size>1.5e6){ blob=await shrink(f); type="image/jpeg"; }
   if(blob.size>20e6){msg.textContent="Arquivo maior que 20 MB.";$("atSave").disabled=false;return}
   const meta={title:$("atTitle").value.trim().slice(0,80)||f.name,link:$("atLink").value,type,name:f.name.slice(0,120),size:blob.size,at:Date.now()};
   if(assetsApi&&db){
    msg.textContent="Enviando…";
    const up=await assetsApi.upload(blob,{type});
    await db.collection("docs").doc().set({...meta,assetId:up.id});
    toast("Anexo salvo e compartilhado");
   }else{
    const lid="a"+uid(); await idbPut(lid,blob); store.attLocal.push({...meta,lid}); save(); toast("Anexo salvo neste aparelho");
   }
   close(); refreshAtt();
  }catch(e){
   const c=e&&e.code; msg.textContent=c==="too_large"?"Arquivo grande demais.":c==="quota_or_state"?"O espaço de anexos do app está cheio.":c==="rate_limited"?"Muitos envios seguidos. Tente de novo em instantes.":"Não deu para salvar. Tente de novo.";
   $("atSave").disabled=false;
  }
 };
}
function shrink(file){return new Promise((res,rej)=>{const img=new Image(),u=URL.createObjectURL(file);img.onload=()=>{const m=2200,k=Math.min(1,m/Math.max(img.width,img.height));const c=document.createElement("canvas");c.width=Math.round(img.width*k);c.height=Math.round(img.height*k);c.getContext("2d").drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(u);c.toBlob(b=>b?res(b):rej(new Error("x")),"image/jpeg",.85)};img.onerror=()=>{URL.revokeObjectURL(u);res(file)};img.src=u})}

/* ---- PDF: desenha as páginas (funciona em Android e iPhone) ---- */
const PDFJS="vendor/";
let pdfLibP=null;
function loadPdfLib(){
 if(window.pdfjsLib) return Promise.resolve(window.pdfjsLib);
 return pdfLibP=pdfLibP||new Promise((res,rej)=>{const sc=document.createElement("script");sc.src=PDFJS+"pdf.min.js";
  sc.onload=()=>{try{window.pdfjsLib.GlobalWorkerOptions.workerSrc=PDFJS+"pdf.worker.min.js";res(window.pdfjsLib)}catch(e){rej(e)}};
  sc.onerror=()=>{pdfLibP=null;rej(new Error("offline"))};document.head.appendChild(sc)});
}
async function renderPdf(src,box){
 try{
  const lib=await loadPdfLib();
  const doc=await lib.getDocument({url:src,isEvalSupported:false}).promise;
  box.innerHTML="";
  const W=Math.min(box.clientWidth||360,900), dpr=Math.min(window.devicePixelRatio||1,2.5);
  for(let n=1;n<=Math.min(doc.numPages,30);n++){
   const pg=await doc.getPage(n), v0=pg.getViewport({scale:1}), sc=W/v0.width, v=pg.getViewport({scale:sc*dpr});
   const c=document.createElement("canvas"); c.width=v.width; c.height=v.height; c.style.width=W+"px";
   box.appendChild(c); await pg.render({canvasContext:c.getContext("2d"),viewport:v}).promise;
  }
 }catch(e){
  box.innerHTML=`<iframe src="${src}" title="PDF"></iframe><p class="small" style="color:#ddd;text-align:center;margin-top:8px">Sem internet o PDF pode não aparecer aqui. Toque em "Abrir ↗".</p>`;
 }
}
/* ---- visualizador ---- */
async function openViewer(key){
 const a=allAtt().find(x=>x.key===key); if(!a) return;
 const src=a.remote?await remoteUrl(a.assetId).catch(()=>null):await localUrl(a.lid).catch(()=>null);
 const ov=document.createElement("div"); ov.className="viewer";
 const canDel=a.remote?!!assetsApi:true;
 ov.innerHTML=`<div class="v-top"><button class="mini" id="vClose">✕ Fechar</button><b>${esc(a.title)}</b>${src?`<a class="mini" href="${src}" target="_blank" rel="noopener">Abrir ↗</a>`:""}</div>
  <div class="v-body">${!src?`<p class="small" style="color:#fff">Arquivo não encontrado neste aparelho.</p>`:isImg(a.type)?`<img src="${src}" alt="">`:`<div class="pdf-pages" id="pdfPages"><p class="small" style="color:#ddd;text-align:center">Carregando PDF…</p></div>`}</div>
  <div class="v-bot"><span class="small" style="color:#cfc8bd">${esc(linkLabel(a.link))}</span>${canDel?`<button class="mini danger" id="vDel">Apagar</button>`:""}${!a.remote&&assetsApi&&db?`<button class="mini dark" id="vUp">Compartilhar</button>`:""}</div>`;
 document.body.appendChild(ov); document.body.classList.add("noscroll");
 const close=()=>{ov.remove();document.body.classList.remove("noscroll")};
 $("vClose").onclick=close;
 if(src&&!isImg(a.type)) renderPdf(src,$("pdfPages"));
 let armed=false; const d=$("vDel"); if(d) d.onclick=async()=>{
  if(!armed){armed=true;d.textContent="Toque de novo para apagar";setTimeout(()=>{armed=false;if(d.isConnected)d.textContent="Apagar"},3500);return}
  try{
   if(a.remote){ await db.collection("docs").doc(a.rid).delete(); try{await assetsApi.delete(a.assetId)}catch(e){} }
   else{ await idbDel(a.lid); store.attLocal=store.attLocal.filter(x=>x.lid!==a.lid); save(); }
   close(); refreshAtt(); toast("Anexo apagado");
  }catch(e){ toast("Não deu para apagar. Tente de novo."); }
 };
 const upb=$("vUp"); if(upb) upb.onclick=async()=>{
  upb.disabled=true; upb.textContent="Enviando…";
  try{ const b=await idbGet(a.lid); const up=await assetsApi.upload(b,{type:a.type});
   const {lid,key:_k,remote:_r,...meta}=a; await db.collection("docs").doc().set({title:meta.title,link:meta.link,type:meta.type,name:meta.name||"",size:meta.size||0,at:meta.at||Date.now(),assetId:up.id});
   await idbDel(a.lid); store.attLocal=store.attLocal.filter(x=>x.lid!==a.lid); save(); close(); refreshAtt(); toast("Agora os dois veem este anexo");
  }catch(e){ upb.disabled=false; upb.textContent="Compartilhar"; toast("Não deu para enviar."); }
 };
}
function refreshAtt(){ safe(renderBook); const a=document.activeElement; if(!editing&&!(a&&$("dayView").contains(a))) safe(()=>showDay(cur)); }
document.addEventListener("click",e=>{const b=e.target.closest("[data-attach]"); if(b){e.preventDefault();e.stopPropagation();openAttachForm(b.dataset.attach)}},true);


/* ================= conta (login Supabase) ================= */
function openAccount(){
 const ov=document.createElement("div"); ov.className="sheet";
 const close=()=>{ov.remove();document.body.classList.remove("noscroll")};
 window.NZ_SESSION.then(sess=>{
  if(sess){
   ov.innerHTML=`<div class="sheet-box"><div class="eyebrow">Conta</div><h3 class="ct" style="margin:6px 0 4px">${esc(sess.user.email)}</h3>
    <p class="small" style="margin-bottom:14px">${SYNC_TXT[syncState]||""}. Tudo o que vocês mudam sincroniza entre os dois celulares.</p>
    <button class="btn ghost" id="acSync">Sincronizar agora</button>
    <button class="btn ghost" id="acOut" style="margin-top:10px;color:var(--alert)">Sair desta conta</button>
    <button class="btn dark" id="acClose" style="margin-top:10px">Fechar</button></div>`;
  }else ov.innerHTML=loginHtml(true);
  document.body.appendChild(ov); document.body.classList.add("noscroll");
  ov.onclick=e=>{if(e.target===ov)close()};
  if(sess){
   $("acClose").onclick=close; $("acSync").onclick=()=>location.reload();
   $("acOut").onclick=async()=>{try{await window.SB.auth.signOut()}catch(e){} location.reload()};
  }else bindLogin(close);
 });
}
function loginHtml(dismissable){
 return `<div class="sheet-box">
  <div class="eyebrow">NZ Road Trip 2027</div><div class="login-hero">Entrar</div>
  <p class="small" style="margin-bottom:12px">Entre para sincronizar roteiro, listas e ingressos entre você e a Grasi.</p>
  <div class="seg sm" id="lgSeg"><button data-m="in" class="on">Já tenho senha</button><button data-m="new">Primeiro acesso</button></div>
  <label class="lbl">E-mail</label><input class="inp" id="lgEmail" type="email" autocomplete="email" inputmode="email" autocapitalize="none">
  <label class="lbl">Senha</label><input class="inp" id="lgPass" type="password" autocomplete="current-password" placeholder="mínimo 8 caracteres">
  <div class="small" id="lgMsg" style="min-height:18px;margin:10px 0"></div>
  <button class="btn dark" id="lgGo">Entrar</button>
  ${dismissable?`<button class="btn ghost" id="lgLater" style="margin-top:10px">Agora não (usar só neste aparelho)</button>`:""}
 </div>`;
}
function bindLogin(close){
 let mode="in";
 document.querySelectorAll("#lgSeg button").forEach(b=>b.onclick=()=>{mode=b.dataset.m;document.querySelectorAll("#lgSeg button").forEach(x=>x.classList.toggle("on",x===b));
  $("lgGo").textContent=mode==="in"?"Entrar":"Criar minha senha e entrar"; $("lgPass").autocomplete=mode==="in"?"current-password":"new-password"; $("lgMsg").textContent=mode==="new"?"Use o e-mail que foi liberado para o app e escolha uma senha.":""});
 const later=$("lgLater"); if(later) later.onclick=()=>{try{localStorage.setItem("nz27skipLogin","1")}catch(e){} close()};
 $("lgGo").onclick=async()=>{
  const email=$("lgEmail").value.trim().toLowerCase(), pass=$("lgPass").value, msg=$("lgMsg"), go=$("lgGo");
  if(!email||pass.length<8){msg.textContent="Preencha o e-mail e uma senha com pelo menos 8 caracteres.";return}
  go.disabled=true; msg.textContent=mode==="in"?"Entrando…":"Criando sua conta…";
  try{
   if(mode==="new"){
    const r=await window.SB.functions.invoke("register",{body:{email,password:pass}});
    if(r.error){ let code=""; try{code=(await r.error.context.json()).error}catch(e){}
     msg.textContent=code==="not_invited"?"Este e-mail não está liberado para o app.":code==="exists"?"Este e-mail já tem senha. Use \"Já tenho senha\".":"Não deu para criar a conta. Verifique a internet e tente de novo.";
     go.disabled=false; return; }
   }
   const {error}=await window.SB.auth.signInWithPassword({email,password:pass});
   if(error){ msg.textContent=/invalid/i.test(error.message)?"E-mail ou senha incorretos.":"Não deu para entrar. Verifique a internet."; go.disabled=false; return; }
   msg.textContent="Pronto!"; location.reload();
  }catch(e){ msg.textContent="Sem conexão. Tente de novo com internet."; go.disabled=false; }
 };
}
async function loginGate(){
 const s=await window.NZ_SESSION;
 const line=$("acctLine"); if(line) line.textContent=s?("Conectado como "+s.user.email):"";
 let skip=false; try{skip=localStorage.getItem("nz27skipLogin")==="1"}catch(e){}
 if(!s&&!skip&&navigator.onLine!==false) openAccount();
}

/* ================= start ================= */
function safe(f){try{f()}catch(e){console.error(e)}}
safe(renderHero); safe(renderResumo); safe(renderBook); safe(renderBudget); safe(renderNotes); safe(renderMaps); safe(renderTripMap); safe(renderLists); safe(initSheet); safe(()=>showDay(cur));
let startView=""; try{startView=location.hash.slice(1)}catch(e){}
safe(()=>go(startView||store.view||"roteiro"));
initSync(); loginGate();
if("serviceWorker" in navigator) addEventListener("load",()=>navigator.serviceWorker.register("sw.js").catch(()=>{}));

